    function lista_registros()
    {
        $sql = "select *,t.tarifa_icono, DATEDIFF(r.registroparqueo_fechalimite,CURDATE()) AS dias_diferencia
                from registro_parqueo r, cliente c, estado e, tarifa_parqueo t
                where                
                r.cliente_id = c.cliente_id and
                r.estado_id = e.estado_id and
                r.estado_id = 1 and r.tarifa_id = t.tarifa_id";
        $registros = $this->Venta_model->consultar($sql);
        
        echo json_encode($registros);
    }
    

    function buscar_filtro()
    {
        /* 
        
        
        
         */
        
        $estado_id = $this->input->post("select_filtro");
        
        // 1 - EN PARQUEO
        if ($estado_id==1){
            $sql = "select *,t.tarifa_icono,DATEDIFF(r.registroparqueo_fechalimite,CURDATE()) AS dias_diferencia 
                    from registro_parqueo r, cliente c, estado e, tarifa_parqueo t
                    where                
                    r.cliente_id = c.cliente_id and
                    r.estado_id = e.estado_id and
                    r.estado_id = {$estado_id} and r.tarifa_id = t.tarifa_id";    
        }
        
        // 2 - SALIDAS DE HOY
        if ($estado_id==2){
            $sql = "select *,t.tarifa_icono,DATEDIFF(r.registroparqueo_fechalimite,CURDATE()) AS dias_diferencia 
                    from registro_parqueo r, cliente c, estado e, tarifa_parqueo t
                    where
                    r.registroparqueo_fechasalida = date(now()) and
                    r.cliente_id = c.cliente_id and
                    r.estado_id = e.estado_id and
                    r.estado_id = 2 and r.tarifa_id = t.tarifa_id";    
        }
        
        // 3 - SALIDAS DE AYER
        if ($estado_id==3){
            $sql = "select *,t.tarifa_icono,DATEDIFF(r.registroparqueo_fechalimite,CURDATE()) AS dias_diferencia 
                    from registro_parqueo r, cliente c, estado e, tarifa_parqueo t
                    where
                    r.registroparqueo_fechasalida = DATE_SUB(DATE(NOW()), INTERVAL 1 DAY) and
                    r.cliente_id = c.cliente_id and
                    r.estado_id = e.estado_id and
                    r.estado_id = 2 and r.tarifa_id = t.tarifa_id";    
        }
        
        // 4 - SALIDAS DE LA SEMANA
        if ($estado_id==4){
            $sql = "select *,t.tarifa_icono,DATEDIFF(r.registroparqueo_fechalimite,CURDATE()) AS dias_diferencia 
                    from registro_parqueo r, cliente c, estado e, tarifa_parqueo t
                    where
                     r.registroparqueo_fechasalida BETWEEN DATE_SUB(DATE(NOW()), INTERVAL 7 DAY) AND DATE(NOW()) and
                    r.cliente_id = c.cliente_id and
                    r.estado_id = e.estado_id and
                    r.estado_id = 2 and r.tarifa_id = t.tarifa_id";    
        }
        
        // 5 - SALIDAS POR FECHA
        if ($estado_id==5){
            
            $fecha_desde = $this->input->post("fecha_desde");
            $fecha_hasta = $this->input->post("fecha_hasta");
            $tipo = $this->input->post("tipo");
            $usuario_id = $this->input->post("usuario_id");
            
            $tipo_registro = " ";
            if($tipo>0){
                $tipo_registro = " and t.tarifa_id = {$tipo} ";
            }
            
            $usuario = " ";
            if($usuario_id>0){
                $usuario = " and t.usuario_idsalida = ".$usuario_id;
            }
            
            
            $sql = "select *,t.tarifa_icono,DATEDIFF(r.registroparqueo_fechalimite,CURDATE()) AS dias_diferencia 
                    from registro_parqueo r, cliente c, estado e, tarifa_parqueo t
                    where
                     r.registroparqueo_fechasalida >= '{$fecha_desde}' and r.registroparqueo_fechasalida <='{$fecha_hasta}' and
                    r.cliente_id = c.cliente_id and
                    r.estado_id = e.estado_id and
                    r.estado_id = 2 and r.tarifa_id = t.tarifa_id {$usuario} {$tipo_registro}";    
        }
        
        
        //echo $sql;
        $registros = $this->Venta_model->consultar($sql);
        
        echo json_encode($registros);
    }
    

