    function recuperar_datos()
    {
            $data['sistema'] = $this->sistema;
            
            $now = "'".date("Y-m-d H:i:s")."'";

            $cliente_codigo = $this->input->post("placa");
            
            
            //primero registrar al cliente
                
                $sql = "SELECT 
                        c.cliente_id,
                        c.cliente_nombre,
                        c.cliente_nombrenegocio,
                        c.cliente_codigo,
                        r.tarifa_id,
                        r.registroparqueo_id,
                        r.registroparqueo_modalidad,
                        r.registroparqueo_fechaingreso,
                        r.registroparqueo_horaingreso,
                        DATE({$now}) AS registroparqueo_fechasalida,
                        TIME({$now}) AS registroparqueo_horasalida,
                      TIMEDIFF({$now}, CONCAT(r.registroparqueo_fechaingreso, ' ', r.registroparqueo_horaingreso)) AS tiempotranscurrido,

                        CONCAT(
                          TIMESTAMPDIFF(DAY, CONCAT(r.registroparqueo_fechaingreso, ' ', r.registroparqueo_horaingreso), {$now}), ' DIA(S), ',

                          LPAD(TIMESTAMPDIFF(HOUR, CONCAT(r.registroparqueo_fechaingreso, ' ', r.registroparqueo_horaingreso), {$now}) % 24, 2, '0'), ' HORA(S), ',

                          LPAD(TIMESTAMPDIFF(MINUTE, CONCAT(r.registroparqueo_fechaingreso, ' ', r.registroparqueo_horaingreso), {$now}) % 60, 2, '0'), ' MIN(S)'
                        ) AS tiempotranscurrido_literal,
                        
                        ROUND(TIMESTAMPDIFF(SECOND, CONCAT(r.registroparqueo_fechaingreso, ' ', r.registroparqueo_horaingreso), {$now}) / 3600, 2) AS horas_transcurridas,

                        
                        if(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(r.registroparqueo_fechaingreso, ' ', r.registroparqueo_horaingreso), {$now}) / 3600, 2) <= 1, t.tarifa_hora1,
                        	if(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(r.registroparqueo_fechaingreso, ' ', r.registroparqueo_horaingreso), {$now}) / 3600, 2) <= 2, t.tarifa_hora1 + t.tarifa_hora2,
                        		if(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(r.registroparqueo_fechaingreso, ' ', r.registroparqueo_horaingreso), {$now}) / 3600, 2) <= 3, t.tarifa_hora1 + t.tarifa_hora2 +t.tarifa_hora3,
									if(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(r.registroparqueo_fechaingreso, ' ', r.registroparqueo_horaingreso), {$now}) / 3600, 2) > 3, t.tarifa_hora1 + t.tarifa_hora2 + t.tarifa_hora3 + (t.tarifa_horaadicional * (TRUNCATE ((TIMESTAMPDIFF(SECOND, CONCAT(r.registroparqueo_fechaingreso, ' ', r.registroparqueo_horaingreso), {$now}) / 3600) - 3, 0)+1) ),0)))) as total
                        

                      FROM
                        registro_parqueo r,
                        cliente c,
                        tarifa_parqueo t
                      WHERE
                        r.estado_id = 1 AND
                        r.tarifa_id = t.tarifa_id AND 
                        c.cliente_codigo = '{$cliente_codigo}' AND 
                        r.cliente_id = c.cliente_id";
                
                //echo $sql;
                $datos = $this->Venta_model->consultar($sql);
                
                $modalidad = $datos[0]["registroparqueo_modalidad"];
               
                if($modalidad=="NOCTURNA"){
                    
                    $sql="SELECT 
                        c.cliente_id,
                        c.cliente_nombre,
                        c.cliente_nombrenegocio,
                        c.cliente_codigo,
                        r.tarifa_id,
                        r.registroparqueo_id,
                        r.registroparqueo_modalidad,
                        r.registroparqueo_fechaingreso,
                        r.registroparqueo_horaingreso,
                        DATE({$now}) AS registroparqueo_fechasalida,
                        TIME({$now}) AS registroparqueo_horasalida,
                      TIMEDIFF({$now}, CONCAT(r.registroparqueo_fechaingreso, ' ', r.registroparqueo_horaingreso)) AS tiempotranscurrido,

                        CONCAT(
                          truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0) + 1, ' NOCHE(S), ',

                          floor((ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/12) -
                        truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0)), ' DIA(S), ',

                         ceil((((ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/12) -
                        truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0)) - 
                        floor((ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/12) -
                        truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0))) *12), ' HRS(S)'
                        ) AS tiempotranscurrido_literal,
                        
                        ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2) AS horas_transcurridas,
                        
                        
                        truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0) + 1 AS nocturnos,

              
                       floor((ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/12) -
                        truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0)) as diurnos,
                        

                        ceil((((ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/12) -
                        truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0)) - 
                        floor((ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/12) -
                        truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0))) *12) as horas,
                        
                        
                        
                        ((truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0) + 1) * t.tarifa_nocturna) +

              
                       ((floor((ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/12) -
                        truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0))) * (t.tarifa_hora1 + t.tarifa_hora2 + t.tarifa_hora3 + (t.tarifa_horaadicional * 9))) + 
                        

                        if(
                        ceil((((ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/12) -
                        truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0)) - 
                        floor((ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/12) -
                        truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0))) *12) <= 1, t.tarifa_hora1,
                        		
                        		if(
                                	ceil((((ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/12) -
                        truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0)) - 
                        floor((ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/12) -
                        truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0))) *12) <= 2, t.tarifa_hora1 + t.tarifa_hora2,
                        
                        		if(
                                ceil((((ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/12) -
                        truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0)) - 
                        floor((ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/12) -
                        truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0))) *12)<=3, t.tarifa_hora1 + t.tarifa_hora2 +t.tarifa_hora3,
                        		
                                                                                
                        t.tarifa_hora1 + t.tarifa_hora2 +t.tarifa_hora3 +
                        (ceil((((ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/12) -
                        truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0)) - 
                        floor((ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/12) -
                        truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0))) *12) - 3) * t.tarifa_horaadicional))) as total,
                        
 
                        
                        if(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2) <= 1, t.tarifa_hora1,
                        	if(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2) <= 2, t.tarifa_hora1 + t.tarifa_hora2,
                        		if(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2) <= 3, t.tarifa_hora1 + t.tarifa_hora2 +t.tarifa_hora3,
									if(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2) > 3, t.tarifa_hora1 + t.tarifa_hora2 + t.tarifa_hora3 + (t.tarifa_horaadicional * (TRUNCATE ((TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600) - 3, 0)+1) ),0)))) + t.tarifa_nocturna +
                                    (truncate(ROUND(TIMESTAMPDIFF(SECOND, CONCAT(DATE_ADD(r.registroparqueo_fechaingreso, INTERVAL 1 DAY), ' ', t.tarifa_nocturnahasta), {$now}) / 3600, 2)/24,0) * t.tarifa_nocturna)  as total2
                        

                      FROM
                        registro_parqueo r,
                        cliente c,
                        tarifa_parqueo t
                      WHERE
                        r.estado_id = 1 AND
                        r.tarifa_id = t.tarifa_id AND 
                        c.cliente_codigo = '{$cliente_codigo}' AND 
                        r.cliente_id = c.cliente_id";
                    
                    $datos = $this->Venta_model->consultar($sql);
                }                
                echo json_encode($datos);
            
    }
    
